import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        String s = new BufferedReader(new InputStreamReader(System.in)).readLine().trim();
        long[] counts = new long[26];
        int i = 0, n = s.length();
        while (i < n) {
            int letter = s.charAt(i++) - 'a';
            // Parse digit by digit: leading zeros are allowed.
            long freq = 0;
            while (i < n && Character.isDigit(s.charAt(i))) freq = freq * 10 + (s.charAt(i++) - '0');
            counts[letter] += freq;
        }
        StringBuilder out = new StringBuilder();
        for (int j = 0; j < 26; j++)
            if (counts[j] > 0) out.append((char) ('a' + j)).append(counts[j]);
        System.out.println(out);
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"
)

func main() {
	in := bufio.NewReaderSize(os.Stdin, 1<<20)
	line, _ := in.ReadString('\n')
	s := strings.TrimSpace(line)
	var counts [26]int64
	for i := 0; i < len(s); {
		letter := s[i] - 'a'
		i++
		// Parse digit by digit: leading zeros are allowed.
		var freq int64
		for i < len(s) && s[i] >= '0' && s[i] <= '9' {
			freq = freq*10 + int64(s[i]-'0')
			i++
		}
		counts[letter] += freq
	}
	var out strings.Builder
	for j, c := range counts {
		if c > 0 {
			out.WriteByte(byte('a' + j))
			out.WriteString(strconv.FormatInt(c, 10))
		}
	}
	fmt.Println(out.String())
}
